def _mergeOrderings(orderings):
    merged = []
    visited = set()
    for ordering in orderings:
        for item in ordering:
            if item not in visited:
                visited.add(item)
                i = len(merged)
                while i > 0 and merged[i - 1] > item:
                    i -= 1
                merged.insert(i, item)
    return merged

