def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        for i, edge in enumerate(self.edges):
            if coord >= edge and coord < self.edges[i + 1]:
                self.values[i] += weight
                break

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if coord < self.edges[0] or coord > self.edges[-1]:
        return
    index = int((coord - self.edges[0]) / self.bin_width)
    if index < len(self.values):
        self.values[index] += weight

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if len(coord) != self.ndim:
        raise ValueError("Coordinate dimension must match histogram dimension: "
                         "len(coord): {lc} ndim: {nd}".format(lc=len(coord), nd=self.ndim))

    for i, (c, e) in enumerate(zip(coord, self.edges)):
        if not (e[0] <= c < e[1]):
            return

    index = [np.where(np.logical_and(e[0] <= coord[i], coord[i] < e[1]))[0][0] for i, e in enumerate(self.edges)]
    self.values[tuple(index)] += weight

